import {
  IWcBindable, RecorderOptions, WcsMediaErrorDetail, WcsRecordedDetail,
} from "../types.js";
import { hasMediaRecorder, normalizeMediaError } from "../media/getUserMedia.js";
import { beginRecording, endRecording } from "../media/recording.js";
import { WcsIoErrorInfo } from "./platformCapability.js";
import { deriveMediaErrorInfo } from "./mediaCapabilities.js";

/**
 * Headless media-recording primitive. Wraps MediaRecorder, consuming a borrowed
 * `MediaStream` (received via `attachStream` over the direct channel — see
 * docs/camera-recorder-tag-design.md §2) and producing a `Blob` clip.
 *
 * Ownership: the stream is BORROWED, never owned. The Core never stops its tracks
 * — that is the camera's job (the acquirer owns release). Stopping here would tear
 * down a stream that may still be previewing.
 *
 * Non-goal: the Core does NOT subscribe to the borrowed tracks' `ended` and does NOT
 * auto-terminate a recording when the underlying stream dies (camera stop / OS
 * revoke / switchCamera re-acquire). Reacting would mean reaching into a stream we do
 * not own. The MediaRecorder keeps running against the now-dead source until an
 * explicit stop(); the consumer (which owns the camera lifecycle) is responsible for
 * stopping the recording when it tears the stream down. stop() then assembles
 * whatever chunks were captured — never throws.
 *
 * Output: `dataavailable` chunks are collected and assembled into one `Blob` on
 * stop, published via `wcs-recorder:recorded`. The `Blob` is structured-clone
 * friendly (a settled value, unlike MediaStream) so it may flow through state.
 * `objectURL` is a managed string — the Core revokes the previous URL before
 * issuing a new one and on dispose. Failures never throw.
 */
export class RecorderCore extends EventTarget {
  static wcBindable: IWcBindable = {
    protocol: "wc-bindable",
    version: 1,
    properties: [
      { name: "recording", event: "wcs-recorder:recording-changed", semantics: "state" },
      { name: "paused", event: "wcs-recorder:paused-changed", semantics: "state" },
      { name: "duration", event: "wcs-recorder:duration-changed", semantics: "state" },
      { name: "mimeType", event: "wcs-recorder:mimetype-changed", semantics: "state" },
      { name: "blob", event: "wcs-recorder:recorded", semantics: "state", getter: (e: Event) => (e as CustomEvent).detail?.blob ?? null },
      { name: "objectURL", event: "wcs-recorder:recorded", semantics: "state", getter: (e: Event) => (e as CustomEvent).detail?.objectURL ?? null },
      { name: "error", event: "wcs-recorder:error", semantics: "state" },
      // Serializable failure taxonomy (stable code / phase / recoverable), or null.
      // Additive bindable output derived from `error` (the DOMException name /
      // "unsupported"/"NoStreamError"/"RecorderError" sentinel); the existing `error`
      // property/event are unchanged. Fires wcs-recorder:error-info-changed. No lane —
      // recording is command-driven.
      { name: "errorInfo", event: "wcs-recorder:error-info-changed", semantics: "state" },
      // event-token: detail = the assembled clip { blob, objectURL, mimeType, duration }.
      { name: "recorded", event: "wcs-recorder:recorded", semantics: "event", getter: (e: Event) => (e as CustomEvent).detail },
      // event-token (timeslice mode): detail = the streamed Blob chunk.
      { name: "dataavailable", event: "wcs-recorder:dataavailable", semantics: "event", getter: (e: Event) => (e as CustomEvent).detail },
    ],
    commands: [
      { name: "attachStream" },
      { name: "start" },
      { name: "stop" },
      { name: "pause" },
      { name: "resume" },
    ],
  };

  private _target: EventTarget;

  private _recording: boolean = false;
  private _paused: boolean = false;
  private _duration: number = 0;
  private _mimeType: string = "";
  private _blob: Blob | null = null;
  private _objectURL: string | null = null;
  private _error: WcsMediaErrorDetail | null = null;
  private _errorInfo: WcsIoErrorInfo | null = null;

  private _recorder: MediaRecorder | null = null;
  private _stream: MediaStream | null = null; // borrowed — never stopped here
  // the stream the live MediaRecorder records (attachStream may swap _stream mid-recording)
  private _recordingStream: MediaStream | null = null;
  private _timeslice: boolean = false;
  private _startTime: number = 0;

  // Monotonic id of the current recording lifecycle. Bumped by every start() and
  // dispose(); each MediaRecorder callback bails if stale so a torn-down/restarted
  // recorder's late event cannot mutate state.
  private _gen: number = 0;

  // The generation of a recording that dispose() stopped: its MediaRecorder still delivers
  // the clip (onstop comes later in a browser), and only that clip gets through — with the
  // type and duration it had when the element went away.
  private _closing: { gen: number; mimeType: string; duration: number } | null = null;

  // SSR: recording is command-driven (attachStream/start), so there is no
  // asynchronous probe to await — readiness is immediate.
  private _ready: Promise<void> = Promise.resolve();

  /**
   * Whether `[wcs/command-not-ready]` was said in this outage: a `start()` refused because the
   * element is not ready loses what it carried, and `error` alone told only a page that binds it.
   * Said once per outage (docs/v4-direction-2026-10.md, the I/O command policy): a stream arriving
   * resets it. Once per element was once per page life — a route puts the same element back on
   * every entry, so the next outage's lost recording went unsaid (docs/seam-apps.md, shift-desk).
   */
  private _toldNotReady = false;

  constructor(target?: EventTarget) {
    super();
    this._target = target ?? this;
  }

  get recording(): boolean { return this._recording; }
  get paused(): boolean { return this._paused; }
  // Finalized at stop/pause only — there is no live ticking timer, so this stays 0
  // from start() until the first pause()/stop() (see _elapsed / onstop / onpause).
  get duration(): number { return this._duration; }
  get mimeType(): string { return this._mimeType; }
  get blob(): Blob | null { return this._blob; }
  get objectURL(): string | null { return this._objectURL; }
  get error(): WcsMediaErrorDetail | null { return this._error; }
  /**
   * The last failure's serializable `WcsIoErrorInfo` (stable `code` / `phase` /
   * `recoverable`), or null. Additive wc-bindable property (event
   * `wcs-recorder:error-info-changed`), derived from `error`; the existing `error`
   * property/event are unchanged.
   */
  get errorInfo(): WcsIoErrorInfo | null { return this._errorInfo; }
  get ready(): Promise<void> { return this._ready; }

  // --- State setters ---

  private _setRecording(v: boolean): void {
    if (this._recording === v) return;
    this._recording = v;
    this._dispatch("wcs-recorder:recording-changed", v);
  }

  private _setPaused(v: boolean): void {
    if (this._paused === v) return;
    this._paused = v;
    this._dispatch("wcs-recorder:paused-changed", v);
  }

  private _setDuration(v: number): void {
    if (this._duration === v) return;
    this._duration = v;
    this._dispatch("wcs-recorder:duration-changed", v);
  }

  private _setMimeType(v: string): void {
    if (this._mimeType === v) return;
    this._mimeType = v;
    this._dispatch("wcs-recorder:mimetype-changed", v);
  }

  // Errors are dispatched on EVERY non-null occurrence by design — each failure is a
  // distinct event, so unlike the value setters this is not content-deduped. Only the
  // null→null transition is collapsed (clearing an already-clear error stays silent).
  // The guard is written on null explicitly so it does NOT depend on callers passing a
  // fresh object: a reused/cached non-null detail would still re-notify.
  private _setError(error: WcsMediaErrorDetail | null): void {
    if (error === null && this._error === null) return;
    this._error = error;
    // Keep the additive `errorInfo` taxonomy in sync with `error`: derive from the
    // error detail (or null on clear). Fires before the `error` event so an observer
    // binding both sees the classification first, mirroring the io-node family.
    this._commitErrorInfo(error === null ? null : deriveMediaErrorInfo(error));
    this._dispatch("wcs-recorder:error", error);
  }

  // Called only from _setError (which already collapses the null→null transition), so
  // errorInfo transitions exactly when error does — no separate guard needed here.
  private _commitErrorInfo(info: WcsIoErrorInfo | null): void {
    this._errorInfo = info;
    this._dispatch("wcs-recorder:error-info-changed", info);
  }

  private _dispatch(type: string, detail: unknown): void {
    this._target.dispatchEvent(new CustomEvent(type, { detail, bubbles: true }));
  }

  // --- Public API ---

  /**
   * Borrow a stream for recording (the direct-channel sink). Synchronous, no
   * await: the live handle is captured by reference and never stored in state.
   * Does NOT stop any previously-borrowed stream — ownership stays with the camera.
   *
   * Re-attaching mid-recording takes effect on the NEXT start(), not the current
   * recording: the live MediaRecorder was already constructed around the previous
   * stream and keeps recording it until stop(). The borrowed reference is swapped so
   * the following start() uses the new stream.
   */
  attachStream(stream: MediaStream): void {
    this._stream = stream;
    // ready again: a start refused in the next outage is said again
    if (stream) this._toldNotReady = false;
  }

  /** Start recording the borrowed stream. Never throws — surfaces `error`. */
  start(options: RecorderOptions = {}): void {
    if (!hasMediaRecorder()) {
      this._setError({ name: "unsupported", message: "MediaRecorder is not available in this environment." });
      return;
    }
    if (!this._stream) {
      this._setError({ name: "NoStreamError", message: "No stream attached. Wire a camera's stream-ready to attachStream first." });
      this._warnNotReady();
      return;
    }
    if (this._recording) return;

    const recOptions: MediaRecorderOptions = {};
    if (options.mimeType && this._isTypeSupported(options.mimeType)) {
      recOptions.mimeType = options.mimeType;
    }
    if (typeof options.audioBitsPerSecond === "number") recOptions.audioBitsPerSecond = options.audioBitsPerSecond;
    if (typeof options.videoBitsPerSecond === "number") recOptions.videoBitsPerSecond = options.videoBitsPerSecond;

    let recorder: MediaRecorder;
    try {
      recorder = new MediaRecorder(this._stream, recOptions);
    } catch (error) {
      this._setError(normalizeMediaError(error));
      return;
    }

    const gen = ++this._gen;
    // per recording: a clip finishing after a disconnect must not take a later one's chunks
    const chunks: Blob[] = [];
    const stream = this._stream;
    this._timeslice = typeof options.timeslice === "number" && options.timeslice > 0;
    const closing = (): boolean => this._closing !== null && this._closing.gen === gen;

    recorder.ondataavailable = (event: BlobEvent): void => {
      if (gen !== this._gen && !closing()) return;
      if (event.data && event.data.size > 0) {
        chunks.push(event.data);
        if (gen !== this._gen) return;
        // a browser that resolved no type at start still types the chunks
        if (!this._mimeType && event.data.type) this._setMimeType(event.data.type);
        if (this._timeslice) {
          this._dispatch("wcs-recorder:dataavailable", event.data);
        }
      }
    };
    // Chromium resolves the type only when recording starts (`mimeType` is "" until then
    // when none was requested): the resolved type is the one the clip has.
    recorder.onstart = (): void => {
      if (gen === this._gen && recorder.mimeType) this._setMimeType(recorder.mimeType);
    };
    recorder.onstop = (): void => {
      endRecording(stream);
      if (this._recordingStream === stream) this._recordingStream = null;
      if (closing()) {
        // stopped by dispose(): recording / paused / duration were published then
        const { mimeType, duration } = this._closing!;
        this._closing = null;
        this._assembleBlob(chunks, mimeType, duration);
        return;
      }
      if (gen !== this._gen) return;
      // When stopped while paused, `_duration` was already finalized in onpause —
      // recomputing _elapsed() here would wrongly include the paused gap (the
      // clock kept running but `_startTime` was not advanced). Keep the held value.
      if (!this._paused) this._setDuration(this._elapsed());
      this._assembleBlob(chunks, this._mimeType, this._duration);
      this._setPaused(false);
      this._setRecording(false);
    };
    recorder.onerror = (event: Event): void => {
      if (gen !== this._gen) return;
      const err = (event as unknown as { error?: unknown }).error;
      this._setError(normalizeMediaError(err ?? { name: "RecorderError" }));
    };
    recorder.onpause = (): void => {
      if (gen !== this._gen) return;
      this._setDuration(this._elapsed());
      this._setPaused(true);
    };
    recorder.onresume = (): void => {
      if (gen !== this._gen) return;
      this._startTime = this._now() - this._duration;
      this._setPaused(false);
    };

    this._recorder = recorder;
    this._setError(null);
    this._setMimeType(recorder.mimeType || recOptions.mimeType || "");
    this._startTime = this._now();
    this._setDuration(0);
    recorder.start(this._timeslice ? options.timeslice : undefined);
    beginRecording(stream);
    this._recordingStream = stream;
    this._setRecording(true);
  }

  private _warnNotReady(): void {
    if (this._toldNotReady) return;
    this._toldNotReady = true;
    console.warn(
      "[@wcstack/camera] [wcs/command-not-ready] start() was refused: no stream is attached, so nothing is recorded. " +
        "It goes to `error` too. Wire a camera's stream to the recorder first. " +
        "(Said once until a stream is attached again.)",
      this._target,
    );
  }

  /** Stop recording; the assembled Blob is published from the recorder's onstop. */
  stop(): void {
    if (this._recorder && this._recorder.state !== "inactive") {
      this._recorder.stop();
    }
  }

  pause(): void {
    if (this._recorder && this._recorder.state === "recording") {
      this._recorder.pause();
    }
  }

  resume(): void {
    if (this._recorder && this._recorder.state === "paused") {
      this._recorder.resume();
    }
  }

  /**
   * Establish monitoring (§3.5). Recording is command-driven — there is no listener
   * or subscription to set up here (the borrowed stream arrives via attachStream and
   * recording is driven by start()/stop()), so observe() is an idempotent no-op that
   * resolves once ready. dispose() is its teardown counterpart.
   */
  observe(): Promise<void> {
    return this._ready;
  }

  /**
   * Stop in-flight recording, revoke the last object URL, drop the borrowed stream.
   *
   * A recording in progress is not thrown away: it stops, and the clip arrives as
   * `wcs-recorder:recorded` when the MediaRecorder delivers it (later, in a browser) — as it
   * does when the stream's tracks end. `recording` / `paused` go back to false at once, with
   * their events: a route the element leaves keeps its nodes (and their bindings) for the
   * next entry, so a reset nobody heard would leave the page showing a recording that is
   * not there.
   */
  dispose(): void {
    const recorder = this._recorder;
    const inFlight = recorder !== null && recorder.state !== "inactive";
    if (inFlight) {
      if (!this._paused) this._setDuration(this._elapsed());
      this._closing = { gen: this._gen, mimeType: this._mimeType, duration: this._duration };
    }
    // Bump the generation so no other callback of this recorder reaches the Core.
    this._gen++;
    this._recorder = null;
    this._revokeUrl();
    // Drop the borrowed reference WITHOUT stopping its tracks — the camera owns it.
    this._stream = null;
    this._setPaused(false);
    this._setRecording(false);
    if (inFlight) {
      try {
        recorder.stop();
      } catch {
        // A recorder already torn down by the environment must not throw here; no clip comes.
        this._closing = null;
        if (this._recordingStream) endRecording(this._recordingStream);
        this._recordingStream = null;
      }
    }
  }

  // --- Internal ---

  private _assembleBlob(chunks: Blob[], mimeType: string, duration: number): void {
    // the chunks carry the type when the recorder resolved none
    const type = mimeType || chunks[0]?.type || "";
    const blob = new Blob(chunks, type ? { type } : undefined);
    // The PREVIOUS clip's object URL is revoked here, before minting the new one — so
    // any consumer still pointing a `<video src>` at the old URL will break once a new
    // recording completes. Consumers must follow the latest `objectURL`/`recorded`
    // value and not pin a stale URL. (The `blob` is unaffected — prefer flowing it.)
    this._revokeUrl();
    const objectURL = this._createUrl(blob);
    this._blob = blob;
    this._objectURL = objectURL;
    const detail: WcsRecordedDetail = {
      blob,
      objectURL,
      mimeType: type,
      duration,
    };
    this._dispatch("wcs-recorder:recorded", detail);
  }

  private _revokeUrl(): void {
    if (this._objectURL && typeof URL !== "undefined" && typeof URL.revokeObjectURL === "function") {
      URL.revokeObjectURL(this._objectURL);
    }
    this._objectURL = null;
  }

  private _createUrl(blob: Blob): string {
    if (typeof URL !== "undefined" && typeof URL.createObjectURL === "function") {
      return URL.createObjectURL(blob);
    }
    return "";
  }

  // Only called after hasMediaRecorder() has confirmed the API, so MediaRecorder
  // and its isTypeSupported are present.
  private _isTypeSupported(type: string): boolean {
    const MR = (globalThis as { MediaRecorder: { isTypeSupported(t: string): boolean } }).MediaRecorder;
    return MR.isTypeSupported(type);
  }

  // performance.now() is universally available wherever MediaRecorder runs
  // (browsers and the happy-dom test env), so no fallback guard is needed.
  private _now(): number {
    return performance.now();
  }

  private _elapsed(): number {
    return Math.max(0, Math.round(this._now() - this._startTime));
  }
}
